// Fails when our own code contains a comment that silences a check.
// AGENTS.md forbids them: fix the code, or ask for the rule to be changed.

import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';

const root = join(import.meta.dirname, '..', '..');

const folders = [
    'app',
    'bootstrap',
    'config',
    'database',
    'resources',
    'routes',
    'tests',
    'tools',
];

const skipped = [
    'bootstrap/cache',
    // Generated by Wayfinder on every check.
    'resources/js/actions',
    'resources/js/routes',
    'resources/js/wayfinder',
    // This file has to name the comments it looks for.
    'tools/check/silencers.ts',
];

const extensions = ['.php', '.ts', '.js', '.vue', '.css'];

const silencers = [
    '@phpstan-ignore',
    'phpstan-ignore-line',
    'phpstan-ignore-next-line',
    '@noRector',
    '@ts-ignore',
    '@ts-expect-error',
    '@ts-nocheck',
    'eslint-disable',
    'prettier-ignore',
    '@vue-ignore',
    '@vue-expect-error',
    '@vue-skip',
];

function filesIn(folder: string): string[] {
    const found: string[] = [];

    for (const name of readdirSync(folder)) {
        const path = join(folder, name);
        const fromRoot = relative(root, path).replaceAll('\\', '/');

        if (skipped.includes(fromRoot)) {
            continue;
        }

        if (statSync(path).isDirectory()) {
            found.push(...filesIn(path));
        } else if (extensions.some((extension) => name.endsWith(extension))) {
            found.push(path);
        }
    }

    return found;
}

const rootFiles = readdirSync(root)
    .filter((name) => extensions.some((extension) => name.endsWith(extension)))
    .map((name) => join(root, name));

const files = [
    ...rootFiles,
    ...folders.flatMap((folder) => filesIn(join(root, folder))),
];

const problems: string[] = [];

for (const file of files) {
    const lines = readFileSync(file, 'utf8').split('\n');

    lines.forEach((line, index) => {
        for (const silencer of silencers) {
            if (line.includes(silencer)) {
                const where = relative(root, file).replaceAll('\\', '/');

                problems.push(`${where}:${String(index + 1)}  ${silencer}`);
            }
        }
    });
}

if (problems.length > 0) {
    console.error('Comments that silence a check are not allowed:');

    for (const problem of problems) {
        console.error(`  ${problem}`);
    }

    process.exit(1);
}

console.log(`No silencing comments in ${String(files.length)} files.`);
